result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/tree.py", "content": """"Cox-Ross-Rubinstein (CRR) binomial option pricer.

u = exp(sigma * sqrt(T/n)), d = 1/u,
risk-neutral probability q = (exp(r*T/n) - d) / (u - d).

Prices European and American calls/puts via O(n^2) backward induction
on arrays.
"""

from __future__ import annotations

import math
from enum import Enum


class Exercise(Enum):
    EUROPEAN = "european"
    AMERICAN = "american"


class OptionType(Enum):
    CALL = "call"
    PUT = "put"


def _validate(S: float, K: float, r: float, sigma: float, T: float, n: int) -> None:
    if S <= 0 or K <= 0:
        raise ValueError("S and K must be positive")
    if sigma < 0:
        raise ValueError("sigma must be non-negative")
    if T <= 0:
        raise ValueError("T must be positive")
    if n < 1:
        raise ValueError("n must be a positive integer")


def risk_neutral_prob(r: float, sigma: float, T: float, n: int) -> float:
    """CRR risk-neutral probability; raises if it falls outside (0, 1)."""
    dt = T / n
    u = math.exp(sigma * math.sqrt(dt))
    d = 1.0 / u
    q = (math.exp(r * dt) - d) / (u - d)
    if not (0.0 < q < 1.0):
        raise ValueError(
            f"risk-neutral probability q={q} outside (0, 1); "
            "check r vs sigma (arbitrage-free condition violated)"
        )
    return q


def price(
    S: float,
    K: float,
    r: float,
    sigma: float,
    T: float,
    n: int,
    kind: OptionType = OptionType.PUT,
    exercise: Exercise = Exercise.EUROPEAN,
) -> float:
    """Price an option on the CRR binomial tree.

    Backward induction over arrays: at each step we hold a vector of
    option values across the m nodes of that time slice, so total work
    is O(n^2) time and O(n) memory.
    """
    _validate(S, K, r, sigma, T, n)

    dt = T / n
    u = math.exp(sigma * math.sqrt(dt))
    d = 1.0 / u
    disc = math.exp(-r * dt)
    q = risk_neutral_prob(r, sigma, T, n)

    is_call = kind is OptionType.CALL
    american = exercise is Exercise.AMERICAN

    # Terminal payoffs at step n: node j has S * u**j * d**(n - j), j = 0..n.
    values = [
        (max(S * u ** (2 * j - n) - K, 0.0) if is_call else max(K - S * u ** (2 * j - n), 0.0))
        for j in range(n + 1)
    ]

    # Backward induction.
    for step in range(n - 1, -1, -1):
        # Continuation: discounted expectation.
        values = [disc * (q * values[j + 1] + (1.0 - q) * values[j]) for j in range(step + 1)]
        if american:
            for j in range(step + 1):
                s_j = S * u ** (2 * j - step)
                intrinsic = (s_j - K) if is_call else (K - s_j)
                if intrinsic > values[j]:
                    values[j] = intrinsic

    return values[0]


# Convenience wrappers -------------------------------------------------

def european_call(S: float, K: float, r: float, sigma: float, T: float, n: int) -> float:
    return price(S, K, r, sigma, T, n, OptionType.CALL, Exercise.EUROPEAN)


def european_put(S: float, K: float, r: float, sigma: float, T: float, n: int) -> float:
    return price(S, K, r, sigma, T, n, OptionType.PUT, Exercise.EUROPEAN)


def american_call(S: float, K: float, r: float, sigma: float, T: float, n: int) -> float:
    return price(S, K, r, sigma, T, n, OptionType.CALL, Exercise.AMERICAN)


def american_put(S: float, K: float, r: float, sigma: float, T: float, n: int) -> float:
    return price(S, K, r, sigma, T, n, OptionType.PUT, Exercise.AMERICAN)


if __name__ == "__main__":
    print(f"European call (n=2000): {european_call(100, 100, 0.05, 0.2, 1.0, 2000):.6f}")
    print(f"American put  (n=2000): {american_put(100, 100, 0.05, 0.2, 1.0, 2000):.6f}")
